package com.example.habitzone.command;
import com.example.habitzone.usecase.SetHabitCategoryUseCase; import java.util.Objects;
public final class SetCategoryCommand implements Command { private final SetHabitCategoryUseCase useCase; public SetCategoryCommand(SetHabitCategoryUseCase useCase){this.useCase=Objects.requireNonNull(useCase);} public String name(){return "set-category";} public String usage(){return "set-category HABIT_NAME CATEGORY";} public CommandResult execute(String args){String a=args==null?"":args.trim();int i=lastWhitespace(a);if(i<=0)return CommandResult.failure(CommandMessages.MISSING_HABIT_NAME);return CommandSupport.executeUseCase(()->useCase.execute(a.substring(0,i),a.substring(i+1)),h->CommandResult.success("Set category for '"+h.name()+"'."));} private static int lastWhitespace(String value){for(int i=value.length()-1;i>=0;i--){if(Character.isWhitespace(value.charAt(i)))return i;}return -1;}}
